'use strict';
const el=id=>document.getElementById(id), candidates=new Map();
let config, wallet, account, estimate, txHash, receipt, busy=false;
let storageKey;
const message=text=>el('status').textContent=text;
const validHash=x=>typeof x==='string' && /^0x[0-9a-f]{64}$/i.test(x);
const shortError=e=>Number(e.code)===4001?'Request declined. Nothing was submitted.':Number(e.code)===-32002?'A wallet request is already open. Check your wallet.':String(e.shortMessage||e.message||'Request failed').slice(0,350);
function add(p,name){if(!p||typeof p.request!=='function'||candidates.has(p))return;candidates.set(p,String(name||'Installed wallet').slice(0,80));}
window.addEventListener('eip6963:announceProvider',e=>{if(e.detail?.info)add(e.detail.provider,e.detail.info.name)});
window.dispatchEvent(new Event('eip6963:requestProvider'));
async function rpc(method,params=[]){const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),20000);try{const r=await fetch(config.rpcUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:abort.signal});if(!r.ok)throw Error('RPC HTTP '+r.status);const d=await r.json();if(d.error)throw Error(d.error.message);return d.result;}finally{clearTimeout(timer)}}
async function verifyWallet(){const chain=await wallet.request({method:'eth_chainId'});if(Number(chain)!==31611)throw Error('Select Mezo Testnet in your wallet, then reconnect.');const accounts=await wallet.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==config.deployer.toLowerCase())throw Error('Select the specified deployment wallet, then reconnect.');return accounts[0];}
function invalidate(){el('deploy').disabled=true;estimate=null;message('Wallet changed. Reconnect to check the network and fees.');}
async function connect(provider){if(busy)return;busy=true;el('connect').disabled=true;try{wallet=provider;await wallet.request({method:'eth_requestAccounts'});if(Number(await wallet.request({method:'eth_chainId'}))!==31611){try{await wallet.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x7b7b'}]})}catch(e){if(Number(e.code)!==4902)throw e;await wallet.request({method:'wallet_addEthereumChain',params:[{chainId:'0x7b7b',chainName:'Mezo Testnet',nativeCurrency:{name:'Bitcoin',symbol:'BTC',decimals:18},rpcUrls:[config.rpcUrl],blockExplorerUrls:[config.explorer]}]});}}
account=await verifyWallet();el('account').textContent=account;
if(Number(await rpc('eth_chainId'))!==31611)throw Error('Unexpected RPC network.');
for(const addr of [config.musd,config.veBTC])if(await rpc('eth_getCode',[addr,'latest'])==='0x')throw Error('Token contract code missing.');
estimate=BigInt(await rpc('eth_estimateGas',[{from:account,data:config.data,value:'0x0'}]));
const price=BigInt(await rpc('eth_gasPrice')),balance=BigInt(await rpc('eth_getBalance',[account,'latest']));
const fee=estimate*price;
el('fee').textContent=(fee/10n**18n).toString()+'.'+(fee%10n**18n).toString().padStart(18,'0').replace(/0+$/,'')+' BTC (estimate; wallet shows final fee)';
if(balance<estimate*price*12n/10n)throw Error('Insufficient test BTC for the estimated fee and buffer.');
el('deploy').hidden=false;el('deploy').disabled=Boolean(txHash);message(txHash?'A deployment was already submitted. Check its status before creating another.':'Ready. Review and approve deployment in your wallet.');
if(wallet.on){wallet.on('accountsChanged',invalidate);wallet.on('chainChanged',invalidate);wallet.on('disconnect',invalidate);}
}catch(e){message(shortError(e));el('deploy').disabled=true;}finally{busy=false;el('connect').disabled=false;}}
el('connect').onclick=()=>{window.dispatchEvent(new Event('eip6963:requestProvider'));if(!candidates.size&&window.ethereum){for(const p of window.ethereum.providers||[window.ethereum])add(p,p.isRabby?'Rabby':p.isMetaMask?'MetaMask':'Installed wallet');}if(candidates.size===1)return connect(candidates.keys().next().value);el('wallets').replaceChildren();for(const [p,name]of candidates){const b=document.createElement('button');b.textContent=name;b.onclick=()=>connect(p);el('wallets').append(b);}if(!candidates.size)message('No wallet detected. Enable your wallet extension and retry.');};
function showTransaction(){el('explorer').href=config.explorer+'/tx/'+txHash;el('explorer').hidden=false;el('check').hidden=false;el('deploy').disabled=true;}
el('deploy').onclick=async()=>{if(busy||txHash||!estimate)return;busy=true;el('deploy').disabled=true;try{await verifyWallet();message('Review deployment in your wallet.');const hash=await wallet.request({method:'eth_sendTransaction',params:[{from:account,data:config.data,value:'0x0',gas:'0x'+(estimate*12n/10n).toString(16)}]});if(!validHash(hash))throw Error('Wallet returned an invalid transaction hash.');txHash=hash;showTransaction();message('Submitted: '+txHash+'\nUse Check submitted transaction until confirmed.');try{localStorage.setItem(storageKey,txHash)}catch{message('Submitted: '+txHash+'\nCopy this hash now; local storage is unavailable.');}}catch(e){message(shortError(e));}finally{busy=false;el('deploy').disabled=Boolean(txHash);}};
el('check').onclick=async()=>{if(busy||!txHash)return;busy=true;try{const r=await rpc('eth_getTransactionReceipt',[txHash]);if(!r){message('Transaction is pending. Check again shortly.');return;}if(Number(r.status)!==1)throw Error('Deployment reverted. Keep the transaction hash for investigation.');if(!r.contractAddress)throw Error('No contract address in receipt.');const tx=await rpc('eth_getTransactionByHash',[txHash]);if(tx.to||tx.from.toLowerCase()!==config.deployer.toLowerCase()||tx.input.toLowerCase()!==config.data.toLowerCase())throw Error('Transaction does not match the prepared deployment.');if(await rpc('eth_getCode',[r.contractAddress,'latest'])==='0x')throw Error('No deployed code found.');receipt={chainId:31611,address:r.contractAddress,transactionHash:txHash,deployer:tx.from,blockNumber:Number(BigInt(r.blockNumber)),musd:config.musd,veBTC:config.veBTC,compiler:config.compiler,evmVersion:config.evmVersion};el('download').hidden=false;try{localStorage.setItem('latch-active-31611-'+config.veBTC.toLowerCase(),JSON.stringify(receipt));message('Deployment confirmed and selected for this browser.\nContract: '+receipt.address+'\nOpen Latch using the link above and connect your wallet. Download the receipt to keep a permanent record.');}catch{message('Deployment confirmed.\nContract: '+receipt.address+'\nDownload the receipt; browser storage is unavailable.');}}catch(e){message(shortError(e));}finally{busy=false;}};
el('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='latch-deployment-v5.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
fetch('deployment.json').then(r=>{if(!r.ok)throw Error('Run node scripts/prepare-deploy.cjs first.');return r.json()}).then(c=>{if(c.chainId!==31611||!/^0x[0-9a-f]+$/i.test(c.data))throw Error('Invalid deployment configuration.');config=c;storageKey='latch-deployment-31611-'+c.veBTC.toLowerCase();el('musd').textContent=c.musd;el('vebtc').textContent=c.veBTC;el('connect').disabled=false;message('Connect your deployment wallet.');try{const saved=localStorage.getItem(storageKey);if(validHash(saved)){txHash=saved;showTransaction();message('Previous transaction for this collateral contract found. Check its status before deploying again.');}}catch{}}).catch(e=>message(shortError(e)));
